    "ArtifactExtractQuery": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "type": "object",
      "properties": {
        "startByte": {
          "description": "Canonical UTF-8 byte offset at which extraction begins; offsets inside a code point are rejected. ArtifactExtractQuery.startByte must be at least 0. ArtifactExtractQuery.startByte must be at most 10485760.",
          "type": "integer",
          "minimum": 0,
          "maximum": 10485760
        },
        "maxBytes": {
          "description": "Maximum UTF-8 encoded bytes to return, bounded to 65536 and never ending in a partial code point. ArtifactExtractQuery.maxBytes must be at least 1. ArtifactExtractQuery.maxBytes must be at most 65536.",
          "type": "integer",
          "minimum": 1,
          "maximum": 65536
        }
      },
      "additionalProperties": false,
      "description": "Optional bounded UTF-8 extraction window for an authorized safe-text artifact version."
    },
    "ContentRangeQuery": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "type": "object",
      "properties": {
        "range": {
          "description": "Standard HTTP Range header value selecting a single byte range of the content; multiple ranges are rejected, and an unsatisfiable range returns 416 with the total size. ContentRangeQuery.range must contain at most 100 UTF-8 bytes.",
          "type": "string",
          "maxLength": 200,
          "pattern": "^bytes=(?:\\d+-\\d*|-\\d+)$",
          "x-utf8-max-bytes": 100
        }
      },
      "additionalProperties": false,
      "description": "Requests a byte range of an artifact version's content via a standard HTTP Range read."
    },
    "ConversationCreate": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "type": "object",
      "properties": {
        "applicationId": {
          "description": "ConversationCreate.applicationId may be null in this transport value.",
          "anyOf": [
            {
              "type": "string",
              "format": "uuid",
              "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
              "description": "Application this conversation belongs to; omit or set null for an organization-wide conversation not scoped to any single application."
            },
            {
              "type": "null",
              "description": "Null indicates that the value is unavailable."
            }
          ]
        },
        "repositoryId": {
          "description": "ConversationCreate.repositoryId may be null in this transport value.",
          "anyOf": [
            {
              "type": "string",
              "format": "uuid",
              "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
              "description": "Repository this conversation belongs to; it must belong to the given application. Omit or set null for an installation-wide conversation, which requires installation-level access rather than falling back from a denied repository."
            },
            {
              "type": "null",
              "description": "Null indicates that the value is unavailable."
            }
          ]
        },
        "title": {
          "type": "string",
          "minLength": 1,
          "maxLength": 300,
          "description": "Display title shown for this conversation in conversation lists. ConversationCreate.title must contain at least 1 characters. ConversationCreate.title must contain at most 300 characters."
        }
      },
      "required": [
        "title"
      ],
      "additionalProperties": false,
      "description": "Starts a new conversation with an immutable access boundary: a repository conversation inherits that repository's application, while omitting repository/application creates an application-only or fully organization-wide conversation. Creating a conversation does not itself create a task."
    },
    "ConversationUpdate": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "type": "object",
      "properties": {
        "title": {
          "description": "Replaces the conversation's current display title; membership and access boundary are unaffected. ConversationUpdate.title must contain at most 300 characters.",
          "type": "string",
          "maxLength": 300
        },
        "archivedAt": {
          "description": "ConversationUpdate.archivedAt may be null in this transport value.",
          "anyOf": [
            {
              "type": "string",
              "format": "date-time",
              "pattern": "^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$",
              "description": "Marks the conversation archived (non-null) or active again (null); archived conversations reject new messages."
            },
            {
              "type": "null",
              "description": "Null indicates that the value is unavailable."
            }
          ]
        }
      },
      "additionalProperties": false,
      "description": "Edits a conversation's title or archived state; its scope (application/repository) cannot be changed here because that boundary is immutable after creation."
    },
    "CursorQuery": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "type": "object",
      "properties": {
        "cursor": {
          "description": "Opaque continuation token from a prior page of the same list operation; rejected if replayed against a different operation, principal, or scope. CursorQuery.cursor must contain at most 512 UTF-8 bytes.",
          "type": "string",
          "maxLength": 65536,
          "x-utf8-max-bytes": 512
        },
        "limit": {
          "description": "Maximum rows returned per page for whichever list operation this shared query is used with; defaults to 25 and cannot exceed 100. CursorQuery.limit must be at least 1. CursorQuery.limit must be at most 100.",
          "type": "integer",
          "minimum": 1,
          "maximum": 100
        }
      },
      "additionalProperties": false,
      "description": "Generic keyset-pagination input reused by every plain list operation (applications, repositories, tasks, runs, workflows, agents, skills, and more); rejects page/offset-style parameters and binds its cursor to the specific operation, principal, and scope that issued it."
    },
