    "RepositoryRulePreviewOrganization": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "type": "object",
      "properties": {
        "organizationId": {
          "type": "string",
          "format": "uuid",
          "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
          "description": "Organization the preview ran for."
        },
        "currentRevision": {
          "type": "integer",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991,
          "description": "Latest published organization rules revision at preview time; 0 when none is published."
        },
        "draftRevision": {
          "type": "integer",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991,
          "description": "Revision the draft would publish as, always currentRevision + 1."
        },
        "draftDigest": {
          "type": "string",
          "pattern": "^[a-f0-9]{64}$",
          "description": "SHA-256 hex of the canonical JSON of {revision, entries} for the draft, equal to the digest publication stores."
        },
        "counts": {
          "type": "object",
          "properties": {
            "repositories": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991,
              "description": "Number of active, non-archived repositories counted."
            },
            "inherited": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991,
              "description": "Repositories with no override that is effective under the draft."
            },
            "overridden": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991,
              "description": "Repositories with at least one override that stays effective under the draft and no override newly superseded by it."
            },
            "newlyLocked": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991,
              "description": "Repositories with at least one override that is effective now but would be superseded by a lock the draft introduces."
            },
            "unsupported": {
              "type": "integer",
              "minimum": -9007199254740991,
              "maximum": 9007199254740991,
              "description": "Repositories whose draft-effective rules hold an enabled require rule whose checker binding is null or names no command of the repository's active fixed policy."
            }
          },
          "required": [
            "repositories",
            "inherited",
            "overridden",
            "newlyLocked",
            "unsupported"
          ],
          "additionalProperties": false,
          "description": "Classification counts over all qualifying repositories."
        },
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "repositoryId": {
                "type": "string",
                "format": "uuid",
                "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
                "description": "Repository this row classifies."
              },
              "applicationId": {
                "type": "string",
                "format": "uuid",
                "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
                "description": "Application that owns the repository."
              },
              "repositoryName": {
                "type": "string",
                "maxLength": 65536,
                "description": "Repository name as registered with Bakery."
              },
              "status": {
                "type": "string",
                "enum": [
                  "inherited",
                  "overridden",
                  "newly_locked"
                ],
                "description": "Inherited when no override stays effective, overridden when one does, newly_locked when the draft supersedes an override that is effective now."
              },
              "unsupported": {
                "type": "boolean",
                "description": "Whether an enabled require rule under the draft has no matching checker command in the repository's active fixed policy."
              },
              "supersededRules": {
                "type": "array",
                "items": {
                  "type": "string",
                  "enum": [
                    "commits.semantic",
                    "changeRequest.semanticTitle",
                    "changeRequest.description",
                    "code.magicNumbers",
                    "code.magicStrings"
                  ],
                  "description": "Rule keys whose saved override the draft would supersede under an organization lock. Each array item follows this format."
                },
                "description": "Rule keys whose saved override the draft would supersede under an organization lock."
              },
              "reactivatedRules": {
                "type": "array",
                "items": {
                  "type": "string",
                  "enum": [
                    "commits.semantic",
                    "changeRequest.semanticTitle",
                    "changeRequest.description",
                    "code.magicNumbers",
                    "code.magicStrings"
                  ],
                  "description": "Rule keys whose saved override is superseded by a lock today and would become effective again because the draft removes that lock. Each array item follows this format."
                },
                "description": "Rule keys whose saved override is superseded by a lock today and would become effective again because the draft removes that lock."
              }
            },
            "required": [
              "repositoryId",
              "applicationId",
              "repositoryName",
              "status",
              "unsupported",
              "supersededRules",
              "reactivatedRules"
            ],
            "additionalProperties": false,
            "description": "One page of affected repositories ordered by repository id ascending. Each array item follows this format."
          },
          "description": "One page of affected repositories ordered by repository id ascending."
        },
        "nextCursor": {
          "anyOf": [
            {
              "type": "string",
              "maxLength": 65536,
              "description": "Opaque cursor for the next page, bound to the organization, principal and draft digest; null on the last page."
            },
            {
              "type": "null",
              "description": "Null indicates that the value is unavailable."
            }
          ],
          "description": "RepositoryRulePreviewOrganization.nextCursor may be null in this transport value."
        }
      },
      "required": [
        "organizationId",
        "currentRevision",
        "draftRevision",
        "draftDigest",
        "counts",
        "items",
        "nextCursor"
      ],
      "additionalProperties": false,
      "description": "The impact of a draft organization rules revision: the current and draft revisions, the draft digest publication would store, counts over every active repository, and a signed-cursor page of affected repositories ordered by repository id. Nothing is stored. One request scans at most 20,000 repositories and 12 MiB of summarized override data (counted in UTF-16 code units; UNPROCESSABLE too_many_repositories or preview_too_large). Each statement runs under a 5 second statement timeout and the whole scan is bounded by the 10 second request deadline (DEPENDENCY_TIMEOUT). Admission is per server process: one scan per organization, one per principal and two per process; a refused request answers DEPENDENCY_UNAVAILABLE with a retryAfterSeconds body field (there is no Retry-After header) and is retried by the caller."
    },
