    "WorkerInventoryReceipt": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "type": "object",
      "properties": {
        "inventoryRevision": {
          "type": "integer",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991,
          "description": "Current host inventory revision after applying the report."
        },
        "readinessRevision": {
          "type": "integer",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991,
          "description": "Current host readiness revision after applying the report."
        },
        "acceptedComponents": {
          "type": "integer",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991,
          "description": "Number of inventory components stored by the report."
        },
        "acceptedChecks": {
          "type": "integer",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991,
          "description": "Number of check results stored by the report."
        },
        "replayed": {
          "type": "boolean",
          "description": "True when the exact report had already been applied and the response was replayed."
        }
      },
      "required": [
        "inventoryRevision",
        "readinessRevision",
        "acceptedComponents",
        "acceptedChecks",
        "replayed"
      ],
      "additionalProperties": false,
      "description": "Bounded acknowledgment of an authenticated inventory/check report: the server-assigned current inventory and readiness revisions, accepted entry counts, and whether this delivery replayed an earlier identical report."
    },
    "WorkerProviderBinding": {
      "$schema": "https://json-schema.org/draft/2020-12/schema",
      "type": "object",
      "properties": {
        "id": {
          "type": "string",
          "format": "uuid",
          "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
          "description": "Stable UUID identifying the provider binding record."
        },
        "workerHostId": {
          "type": "string",
          "format": "uuid",
          "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
          "description": "Stable UUID of the machine this binding places the account on."
        },
        "componentKey": {
          "type": "string",
          "maxLength": 65536,
          "description": "Harness component key this binding authorizes."
        },
        "provider": {
          "type": "string",
          "maxLength": 65536,
          "description": "Provider key the binding routes work toward."
        },
        "billingRoute": {
          "type": "string",
          "enum": [
            "subscription",
            "api_metered",
            "local"
          ],
          "description": "Billing route the work on this binding follows."
        },
        "paymentMethodSupported": {
          "type": "boolean",
          "description": "Whether the binding's billing route is one its coding agent accepts (#68). False marks a binding saved before the rule that needs attention; new and changed bindings are refused instead."
        },
        "enabled": {
          "type": "boolean",
          "description": "Whether the binding may be used; disabling blocks new use immediately."
        },
        "authMode": {
          "type": "string",
          "enum": [
            "host_native",
            "api_secret"
          ],
          "description": "How credentials are obtained: the host-native harness account or a referenced Bakery secret."
        },
        "credentialLocation": {
          "type": "string",
          "enum": [
            "harness_host",
            "bakery_secret"
          ],
          "description": "Where credentials live: local to the harness host, or referenced through a scoped secret."
        },
        "modelProviderAccountId": {
          "anyOf": [
            {
              "type": "string",
              "format": "uuid",
              "pattern": "^([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$",
              "description": "Verified organization-owned account linked to this binding; null until one completes authentication."
            },
            {
              "type": "null",
              "description": "Null indicates that the projected value is unavailable."
            }
          ],
          "description": "WorkerProviderBinding.modelProviderAccountId may be null in the safe projection."
        },
        "authGeneration": {
          "type": "integer",
          "minimum": -9007199254740991,
          "maximum": 9007199254740991,
          "description": "Monotonic binding auth generation; incremented on each winning authentication."
        },
        "lastCheckedAt": {
          "anyOf": [
            {
              "type": "string",
              "format": "date-time",
              "pattern": "^(?:(?:\\d\\d[2468][048]|\\d\\d[13579][26]|\\d\\d0[48]|[02468][048]00|[13579][26]00)-02-29|\\d{4}-(?:(?:0[13578]|1[02])-(?:0[1-9]|[12]\\d|3[01])|(?:0[469]|11)-(?:0[1-9]|[12]\\d|30)|(?:02)-(?:0[1-9]|1\\d|2[0-8])))T(?:(?:[01]\\d|2[0-3]):[0-5]\\d:[0-5]\\d(?:\\.\\d+)?(?:Z|([+-](?:[01]\\d|2[0-3]):[0-5]\\d)))$",
              "description": "UTC timestamp of the last auth-health check, when one exists."
            },
            {
              "type": "null",
              "description": "Null indicates that the projected value is unavailable."
            }
          ],
          "description": "WorkerProviderBinding.lastCheckedAt may be null in the safe projection."
        },
        "safeProblem": {
          "anyOf": [
            {
              "type": "string",
              "maxLength": 65536,
              "description": "Bounded safe Problem reference for the latest failure, when any."
            },
            {
              "type": "null",
              "description": "Null indicates that the projected value is unavailable."
            }
          ],
          "description": "WorkerProviderBinding.safeProblem may be null in the safe projection."
        }
      },
      "required": [
        "id",
        "workerHostId",
        "componentKey",
        "provider",
        "billingRoute",
        "paymentMethodSupported",
        "enabled",
        "authMode",
        "credentialLocation",
        "modelProviderAccountId",
        "authGeneration",
        "lastCheckedAt",
        "safeProblem"
      ],
      "additionalProperties": false,
      "description": "One explicit authorized account placement binding a provider/billing route to a machine's harness component. Auth generation increments on each authentication so stale host reports are fenced; safeProblem carries a bounded safe Problem reference. Provider identity is not mutable freeform config, secret references never imply unrestricted access, and no response contains credential material."
    },
